glsl4.vert:
precision highp float;
layout(set = 0, binding = 0) uniform CCGlobal {
  highp   vec4 cc_time;
  mediump vec4 cc_screenSize;
  mediump vec4 cc_nativeSize;
  mediump vec4 cc_probeInfo;
  mediump vec4 cc_debug_view_mode;
};
layout(set = 0, binding = 1) uniform CCCamera {
  highp   mat4 cc_matView;
  highp   mat4 cc_matViewInv;
  highp   mat4 cc_matProj;
  highp   mat4 cc_matProjInv;
  highp   mat4 cc_matViewProj;
  highp   mat4 cc_matViewProjInv;
  highp   vec4 cc_cameraPos;
  mediump vec4 cc_surfaceTransform;
  mediump vec4 cc_screenScale;
  mediump vec4 cc_exposure;
  mediump vec4 cc_mainLitDir;
  mediump vec4 cc_mainLitColor;
  mediump vec4 cc_ambientSky;
  mediump vec4 cc_ambientGround;
  mediump vec4 cc_fogColor;
  mediump vec4 cc_fogBase;
  mediump vec4 cc_fogAdd;
  mediump vec4 cc_nearFar;
  mediump vec4 cc_viewPort;
};
layout(set = 2, binding = 0) uniform CCLocal {
  highp mat4 cc_matWorld;
  highp mat4 cc_matWorldIT;
  highp vec4 cc_lightingMapUVParam;
  highp vec4 cc_localShadowBias;
  highp vec4 cc_reflectionProbeData1;
  highp vec4 cc_reflectionProbeData2;
  highp vec4 cc_reflectionProbeBlendData1;
  highp vec4 cc_reflectionProbeBlendData2;
};
layout(location = 0) in vec3 a_position;
layout(location = 1) in vec3 a_normal;
layout(location = 2) in vec2 a_texCoord;
layout(location = 0) out vec2 v_uv;
layout(location = 1) out float v_worldY;
layout(location = 2) out vec3 v_normal;
layout(location = 3) out vec3 v_viewDir;
void main () {
  vec4 world = cc_matWorld * vec4(a_position, 1.0);
  v_uv = a_texCoord;
  v_worldY = world.y;
  v_normal = normalize((cc_matWorldIT * vec4(a_normal, 0.0)).xyz);
  v_viewDir = normalize(cc_cameraPos.xyz - world.xyz);
  gl_Position = cc_matProj * cc_matView * world;
}

glsl4.frag:
precision highp float;
layout(set = 0, binding = 0) uniform CCGlobal {
  highp   vec4 cc_time;
  mediump vec4 cc_screenSize;
  mediump vec4 cc_nativeSize;
  mediump vec4 cc_probeInfo;
  mediump vec4 cc_debug_view_mode;
};
layout(set = 0, binding = 1) uniform CCCamera {
  highp   mat4 cc_matView;
  highp   mat4 cc_matViewInv;
  highp   mat4 cc_matProj;
  highp   mat4 cc_matProjInv;
  highp   mat4 cc_matViewProj;
  highp   mat4 cc_matViewProjInv;
  highp   vec4 cc_cameraPos;
  mediump vec4 cc_surfaceTransform;
  mediump vec4 cc_screenScale;
  mediump vec4 cc_exposure;
  mediump vec4 cc_mainLitDir;
  mediump vec4 cc_mainLitColor;
  mediump vec4 cc_ambientSky;
  mediump vec4 cc_ambientGround;
  mediump vec4 cc_fogColor;
  mediump vec4 cc_fogBase;
  mediump vec4 cc_fogAdd;
  mediump vec4 cc_nearFar;
  mediump vec4 cc_viewPort;
};
vec4 CCFragOutput (vec4 color) {
  return color;
}
layout(set = 1, binding = 1) uniform sampler2D mainTexture;
layout(set = 1, binding = 0) uniform HitFlashParams {
  vec4 mainColor;
  vec4 flashColor;
  float flashProgress;
  float flashStrength;
  float edgeWidth;
  float worldCenterY;
  float worldHalfY;
};
layout(location = 0) in vec2 v_uv;
layout(location = 1) in float v_worldY;
layout(location = 2) in vec3 v_normal;
layout(location = 3) in vec3 v_viewDir;
vec4 frag () {
  float p = clamp(flashProgress, 0.0, 1.0);
  float fade = 1.0 - smoothstep(0.12, 1.0, p);
  vec4 baseColor = texture(mainTexture, v_uv) * mainColor;
  float halfY = max(worldHalfY, 0.001);
  float yN = clamp((v_worldY - worldCenterY) / halfY, -1.0, 1.0);
  float topDistance = clamp(1.0 - yN, 0.0, 1.0);
  float bottomDistance = clamp(1.0 + yN, 0.0, 1.0);
  float topWidth = edgeWidth * 0.62;
  float bottomWidth = edgeWidth * 1.22;
  float topLine = 1.0 - smoothstep(topWidth * 0.12, topWidth, topDistance);
  float bottomLine = 1.0 - smoothstep(bottomWidth * 0.12, bottomWidth, bottomDistance);
  float topSpread = pow(1.0 - smoothstep(0.0, 1.12, topDistance), 0.72);
  float bottomSpread = pow(1.0 - smoothstep(0.0, 1.12, bottomDistance), 0.72);
  float edgeSpread = max(topSpread, bottomSpread);
  float rim = pow(1.0 - abs(dot(normalize(v_normal), normalize(v_viewDir))), 3.0);
  float highlight = ((topLine * 1.08 + bottomLine * 1.32) * 1.35 + edgeSpread * 0.72 + rim * 0.02) * fade * flashStrength;
  vec3 color = baseColor.rgb + flashColor.rgb * highlight;
  return CCFragOutput(vec4(color, baseColor.a));
}
layout(location = 0) out vec4 cc_FragColor;
void main() { cc_FragColor = frag(); }

